entries[26915] = { ["name"] = "Halskette des Diamantturms", ["text"] = "Wirken in 45 sek.\nTools:\nJuweliersset\nReagenzien:\nAzerothischer Diamant (2), Thoriumfassung (2), Arkanitbarren (2)\nHalskette des Diamantturms\nWird beim Anlegen gebunden\nHals\n+3 Arkanwiderstand\n+3 Feuerwiderstand\n+3 Naturwiderstand\n+3 Frostwiderstand\n+3 Schattenwiderstand\n56\nAnlegen: Erhöht Verteidigungswertung um 17." }
