entries[26918] = { ["name"] = "Arkanitschwertanhänger", ["text"] = "Wirken in 45 sek.\nTools:\nJuweliersset\nReagenzien:\nArkanitbarren (4), Essenz der Erde (4), Essenz der Luft (4)\nArkanitschwertanhänger\nWird beim Anlegen gebunden\nHals\n58\nAnlegen: Erhöht die Angriffskraft um 40." }
entries[26920] = { ["name"] = "Blutkrone", ["text"] = "Wirken in 45 sek.\nTools:\nJuweliersset\nReagenzien:\nThoriumbarren (8), Blut des Berges (2), Sternrubin (4), Blut von Helden (2)\nBlutkrone\nWird beim Anlegen gebunden\nKopf Stoff\n75 Rüstung\nHaltbarkeit 50 / 50\n60\nAnlegen: Erhöht Eure kritische Trefferwertung um 28.\nAnlegen: Heilt Euch um 12 to 18, wenn Ihr einen kritischen Treffer erzielt." }
