entries[26992] = { ["name"] = "Dornen", ["text"] = "17% von Grundmana 30 Meter Reichweite\nSofort\nAus dem befreundeten Ziel sprießen Dornen, die jedem Angreifer 25 Naturschaden zufügen. Hält 10 min lang an." }
