entries[26996] = { ["name"] = "Zermalmen", ["text"] = "15 Wut Nahkampfreichweite\nNächster Nahkampf\nBenötigt Bärengestalt, Terrorbärengestalt\nEin heftiger Angriff, der den Nahkampfschaden um 290 erhöht und ein hohes Maß an Bedrohung erzeugt. Effekte, die den Blutungsschaden erhöhen, erhöhen ebenfalls den Schaden von 'Zermalmen'." }
entries[26997] = { ["name"] = "Prankenhieb (Bär)", ["text"] = "20 Wut 8 Meter Reichweite\nSpontanzauber\nBenötigt Bärengestalt, Terrorbärengestalt\nSchlägt in der Nähe befindliche Feinde und verursacht 76 Schaden. Der Schaden wird durch Angriffskraft erhöht." }
entries[26998] = { ["name"] = "Demoralisierendes Gebrüll", ["text"] = "10 Wut\nSpontanzauber\nBenötigt Bärengestalt, Terrorbärengestalt\nDer Druide brüllt und verringert damit die Nahkampfangriffskraft von in der Nähe befindlichen Feinden um 228. Hält 30 sec lang an." }
entries[27000] = { ["name"] = "Klaue", ["text"] = "45 Energie Nahkampfreichweite\nSofort\nBenötigt Katzengestalt\nDen Feind mit Klauen beharken und ihm so zusätzlich 190 Schaden zufügen. Gewährt 1 Combopunkt.\n(Procchance: 40%)" }
entries[27001] = { ["name"] = "Schreddern", ["text"] = "60 Energie Nahkampfreichweite\nSofort\nBenötigt Katzengestalt\nSchreddert das Ziel, verursacht 225% Schaden plus 236. Muss hinter dem Ziel sein. Gewährt 1 Combopunkt. Effekte, die den Blutungsschaden erhöhen, erhöhen auch den Schaden von 'Schreddern'" }
entries[27002] = { ["name"] = "Schreddern", ["text"] = "60 Energie Nahkampfreichweite\nSofort\nBenötigt Katzengestalt\nSchreddert das Ziel, verursacht 225% Schaden plus 405. Muss hinter dem Ziel sein. Gewährt 1 Combopunkt. Effekte, die den Blutungsschaden erhöhen, erhöhen auch den Schaden von 'Schreddern'" }
entries[27003] = { ["name"] = "Krallenhieb", ["text"] = "40 Energie Nahkampfreichweite\nSofort\nBenötigt Katzengestalt\nAttackiert das Ziel mit Krallen, fügt (Attack power / 100 + 90) Blutungsschaden sowie 9 sec lang insgesamt (138 * 3 + Attack power * 0.18) zusätzlichen Schaden zu. Gewährt 1 Combopunkt." }
entries[27004] = { ["name"] = "Ducken", ["text"] = "20 Energie Nahkampfreichweite\nSofort 10 sek. Abklingzeit\nBenötigt Katzengestalt\nDucken verursacht zwar keinen Schaden, verringert aber Eure Bedrohung und senkt die Wahrscheinlichkeit, dass der Feind Euch angreift." }
entries[27005] = { ["name"] = "Verheeren", ["text"] = "60 Energie Nahkampfreichweite\nSofort\nBenötigt Katzengestalt\nVerheert das Ziel, wobei dem Ziel 385% Schaden plus 566 zugefügt wird. Muss schleichen und hinter dem Ziel sein. Gewährt 1 Combopunkt." }
entries[27006] = { ["name"] = "Anspringen", ["text"] = "50 Energie Nahkampfreichweite\nSofort\nBenötigt Katzengestalt\nAnspringen betäubt das Ziel 3 sec lang und verursacht im Verlauf von 18 sec insgesamt 600 Schaden. Erfordert, dass der Druide schleicht. Gewährt 1 Combopunkt." }
entries[27007] = { ["name"] = "Anspringblutung", ["text"] = "Nahkampfreichweite\nSofort\nAnspringen betäubt das Ziel 3 sec lang und verursacht im Verlauf von 18 sec insgesamt 600 Schaden. Erfordert, dass der Druide schleicht. Gewährt 1 Combopunkt." }
entries[27008] = { ["name"] = "Zerfetzen", ["text"] = "30 Energie Nahkampfreichweite\nSofort\nBenötigt Katzengestalt\nFinishing-Move, der Schaden im Lauf der Zeit verursacht. Der Schaden erhöht sich pro Combopunkt sowie durch Eure Angriffskraft:\n1 Punkt: [(24 + 47 * 1 + 0.01 * Attack power) * 6 ] Schaden im Verlauf von 12 sec.\n2 Punkte: [(24 + 47 * 2 + 0.02 * Attack power) * 6 ] Schaden im Verlauf von 12 sec.\n3 Punkte: [(24 + 47 * 3 + 0.03 * Attack power) * 6 ] Schaden im Verlauf von 12 sec.\n4 Punkte: [(24 + 47 * 4 + 0.04 * Attack power) * 6 ] Schaden im Verlauf von 12 sec.\n5 Punkte: [(24 + 47 * 5 + 0.05 * Attack power) * 6 ] Schaden im Verlauf von 12 sec." }
