entries[27012] = { ["name"] = "Hurrikan", ["text"] = "81% von Grundmana 30 Meter Reichweite\nKanalisiert (Wirken in 10 sek.)\nErzeugt einen wütenden Sturm im Zielgebiet, der Feinden alle 1 Sek. 306 Naturschaden zufügt\n\nGlyphe 'Hurrikan'\nihr Bewegungstempo um 20% verringert\n\nund die Zeit zwischen ihren Angriffen um 20% erhöht. Hält 10 sec lang an. Ein Druide muss seine Kräfte kanalisieren, um den Zauber aufrechtzuerhalten." }
