entries[27016] = { ["name"] = "Schlangenbiss", ["text"] = "9% von Grundmana 35 Meter Reichweite\nBenötigt Distanzwaffe\nFügt dem Ziel im Verlauf von 15 sec (Ranged attack power * 0.2 + 132 * 15 / 3) Naturschaden zu. Es kann immer nur ein Biss oder Stich pro Jäger auf einem einzelnen Ziel aktiv sein." }
