entries[27022] = { ["name"] = "Salve", ["text"] = "17% von Grundmana 35 Meter Reichweite\nBenötigt Distanzwaffe\nFeuert kontinuierlich eine Salve Munition auf das Zielgebiet. Fügt feindlichen Zielen im Umkreis von 8 Metern 6 sec lang alle 1.00 Sek. (Ranged attack power * 0.083700 + 168) Arkanschaden zu." }
entries[27023] = { ["name"] = "Feuerbrandfalle", ["text"] = "9% von Grundmana\nSofort 30 sek. Abklingzeit\nEine Feuerfalle platzieren, die dem ersten sich nähernden Feind im Verlauf von 15 sec insgesamt [(Ranged attack power * ( 2 / 100) + 197) * 5 ] Feuerschaden zufügt. Die Falle bleibt 30 sec lang bestehen. Es kann immer nur jeweils eine Falle aktiv sein." }
