entries[27065] = { ["name"] = "Gezielter Schuss", ["text"] = "8% von Grundmana 35 Meter Reichweite\n10 sek. Abklingzeit\nBenötigt Distanzwaffe\nEin gezielter Schuss, der den Distanzschaden um 205 erhöht und auf das Ziel gewirkte Heileffekte um 50% verringert. Hält 10 sec lang an." }
entries[27067] = { ["name"] = "Gegenangriff", ["text"] = "3% von Grundmana Nahkampfreichweite\nSofort 5 sek. Abklingzeit\nEin Schlag, der aktiv wird, nachdem ein gegnerischer Angriff pariert wurde. Dieser Angriff verursacht (Attack power * 0.2 + 196) Schaden und macht das Ziel 5 sec lang bewegungsunfähig. Auf 'Gegenangriff' kann nicht mit 'Blocken', 'Ausweichen' oder 'Parieren' reagiert werden." }
entries[27068] = { ["name"] = "Stich des Flügeldrachen", ["text"] = "8% von Grundmana 35 Meter Reichweite\n1 min Abklingzeit\nBenötigt Distanzwaffe\nVerschießt einen Stachel, der das Ziel 30 sec lang einschläfert. Jeglicher erlittene Schaden hebt den Effekt wieder auf. Wenn das Ziel wieder aufwacht, verursacht der Stich im Verlauf von 6 sec insgesamt 942 Naturschaden. Auf dem Ziel kann gleichzeitig nur ein Biss oder Stich pro Jäger aktiv sein." }
entries[27069] = { ["name"] = "Stich des Flügeldrachen", ["text"] = "Unbegrenzte Reichweite\nSofort\nVerschießt einen Stachel, der das Ziel 30 sec lang einschläfert. Jeglicher erlittene Schaden hebt den Effekt wieder auf. Wenn das Ziel wieder aufwacht, verursacht der Stich im Verlauf von 6 sec insgesamt 942 Naturschaden. Auf dem Ziel kann gleichzeitig nur ein Biss oder Stich pro Jäger aktiv sein." }
entries[27070] = { ["name"] = "Feuerball", ["text"] = "19% von Grundmana 35 Meter Reichweite\nWirken in 3.5 sek.\nSchleudert eine glühende Kugel hinaus, die 649 to 821 Feuerschaden sowie 8 sec lang insgesamt 84 zusätzlichen Feuerschaden verursacht." }
entries[27071] = { ["name"] = "Frostblitz", ["text"] = "11% von Grundmana 30 Meter Reichweite\nWirken in 3 sek.\nSchleudert einen Frostblitz auf den Feind, der [Quellwert] bis [Quellwert] Frostschaden verursacht und sein Bewegungstempo 9 sec lang um 40% verringert.", ["unresolvedValues"] = true }
entries[27072] = { ["name"] = "Frostblitz", ["text"] = "11% von Grundmana 30 Meter Reichweite\nWirken in 3 sek.\nSchleudert einen Frostblitz auf den Feind, der [Quellwert] bis [Quellwert] Frostschaden verursacht und sein Bewegungstempo 9 sec lang um 40% verringert.", ["unresolvedValues"] = true }
entries[27073] = { ["name"] = "Versengen", ["text"] = "8% von Grundmana 30 Meter Reichweite\nWirken in 1.5 sek.\nVersengt den Feind und fügt ihm 278 to 327 Feuerschaden zu." }
entries[27074] = { ["name"] = "Versengen", ["text"] = "8% von Grundmana 30 Meter Reichweite\nWirken in 1.5 sek.\nVersengt den Feind und fügt ihm 315 to 371 Feuerschaden zu." }
entries[27075] = { ["name"] = "Arkane Geschosse", ["text"] = "31% von Grundmana 30 Meter Reichweite\nKanalisiert (Wirken in 5 sek.)\nSchleudert arkane Geschosse auf den Feind und verursacht 5 sec lang alle 1 Sek. 245 Arkanschaden." }
entries[27076] = { ["name"] = "Arkane Geschosse", ["text"] = "30 Meter Reichweite\nSofort\nSchleudert arkane Geschosse auf den Feind und verursacht 5 sec lang alle 1 Sek. 245 Arkanschaden." }
entries[27078] = { ["name"] = "Feuerschlag", ["text"] = "21% von Grundmana 20 Meter Reichweite\nSofort 8 sek. Abklingzeit\nÜberzieht den Feind mit 555 to 654 Feuerschaden." }
entries[27079] = { ["name"] = "Feuerschlag", ["text"] = "21% von Grundmana 20 Meter Reichweite\nSofort 8 sek. Abklingzeit\nÜberzieht den Feind mit 682 to 805 Feuerschaden." }
entries[27080] = { ["name"] = "Arkane Explosion", ["text"] = "22% von Grundmana\nSofort\nVerursacht eine Explosion arkaner Magie um den Zaubernden herum und fügt allen Zielen in einem Umkreis von 10 Metern 313 to 338 Arkanschaden zu." }
entries[27082] = { ["name"] = "Arkane Explosion", ["text"] = "22% von Grundmana\nSofort\nVerursacht eine Explosion arkaner Magie um den Zaubernden herum und fügt allen Zielen in einem Umkreis von 10 Metern 385 to 415 Arkanschaden zu." }
entries[27085] = { ["name"] = "Blizzard", ["text"] = "74% von Grundmana 30 Meter Reichweite\nKanalisiert (Wirken in 8 sek.)\nEisbrocken prasseln auf das Zielgebiet nieder und verursachen 8 sec lang insgesamt [Quellwert] Frostschaden.", ["unresolvedValues"] = true }
entries[27086] = { ["name"] = "Flammenstoß", ["text"] = "30% von Grundmana 30 Meter Reichweite\nWirken in 2 sek.\nLässt eine Feuersäule niedergehen, die alle Feinde im Gebiet verbrennt und ihnen zunächst 480 to 585 Feuerschaden und zusätzlich 8 sec lang 424 Feuerschaden zufügt." }
entries[27087] = { ["name"] = "Kältekegel", ["text"] = "25% von Grundmana\nSofort 10 sek. Abklingzeit\nZiele in einem kegelförmigen Bereich vor dem Zaubernden erleiden [Quellwert] bis [Quellwert] Frostschaden und ihr Bewegungstempo wird 8 sec lang um 50% verringert.", ["unresolvedValues"] = true }
entries[27088] = { ["name"] = "Frostnova", ["text"] = "7% von Grundmana\nSofort 25 sek. Abklingzeit\nFügt in der Nähe des Zaubernden befindlichen Feinden [Quellwert] bis [Quellwert] Frostschaden zu und friert sie bis zu 8 sec lang ein. Erlittener Schaden kann den Effekt unterbrechen.", ["unresolvedValues"] = true }
entries[27089] = { ["name"] = "Trinken", ["text"] = "Sofort\nStellt im Verlauf von 30 sec insgesamt 7200 Mana wieder her. Ihr müsst beim Trinken sitzen bleiben." }
entries[27090] = { ["name"] = "Wasser herbeizaubern", ["text"] = "40% von Grundmana\nWirken in 3 sek.\nZaubert 20 Schläuche Eiswasser herbei und versorgt den Magier sowie seine Verbündeten mit etwas Trinkbarem.\n\nHerbeigezauberte Gegenstände verschwinden, wenn Ihr Euch länger als 15 Minuten ausloggt." }
entries[27094] = { ["name"] = "Essen", ["text"] = "Sofort 1 min Abklingzeit\nStellt im Verlauf von 30 sec insgesamt 4320 Gesundheit wieder her. Ihr müsst beim Essen sitzen bleiben." }
entries[27095] = { ["name"] = "Intuition", ["text"] = "Erhöht den Durch Eure Fähigkeiten 'Hinterhalt' und 'Erdrosseln' verursachten Schaden um 2% und verleiht Euch eine Chance von 40%, zu entdecken, wenn Spieler Eure Verstohlenheit durchschauen." }
entries[27096] = { ["name"] = "Intuition", ["text"] = "Erhöht den Durch Eure Fähigkeiten 'Hinterhalt' und 'Erdrosseln' verursachten Schaden um 3% und verleiht Euch eine Chance von 60%, zu entdecken, wenn Spieler Eure Verstohlenheit durchschauen." }
entries[27097] = { ["name"] = "Intuition", ["text"] = "Erhöht den Durch Eure Fähigkeiten 'Hinterhalt' und 'Erdrosseln' verursachten Schaden um 4% und verleiht Euch eine Chance von 80%, zu entdecken, wenn Spieler Eure Verstohlenheit durchschauen." }
entries[27099] = { ["name"] = "Intuition", ["text"] = "Erhöht den Durch Eure Fähigkeiten 'Hinterhalt' und 'Erdrosseln' verursachten Schaden um 5% und verleiht Euch eine Chance von 100%, zu entdecken, wenn Spieler Eure Verstohlenheit durchschauen." }
entries[27101] = { ["name"] = "Manaedelstein herbeizaubern", ["text"] = "75% von Grundmana\nWirken in 3 sek.\nZaubert einen Manasmaragd herbei, der zum sofortigen Wiederherstellen von 2340 to 2460 Mana verwendet werden kann. 3 Aufladungen." }
entries[27103] = { ["name"] = "Mana auffüllen", ["text"] = "Sofort 1 min Abklingzeit\nStellt 2340 to 2460 Mana wieder her." }
