entries[27124] = { ["name"] = "Eisrüstung", ["text"] = "24% von Grundmana\nSofort\nErhöht die Rüstung um 645 und den Frostwiderstand um 18. Wenn ein Feind den Zaubernden schlägt, kann 5 sec lang sein Bewegungstempo um 30% verlangsamt und die Zeit zwischen seinen Angriffen um 25% erhöht werden. Es kann immer nur ein Rüstungszauber zur selben Zeit auf dem Magier aktiv sein. Hält 30 min lang an." }
entries[27125] = { ["name"] = "Magische Rüstung", ["text"] = "26% von Grundmana\nSofort\nErhöht den Widerstand gegen alle Arten von Magie um 18 und gewährt dem Zaubernden 50% Manaregeneration während des Zauberwirkens. Es kann immer nur ein Rüstungszauber zur selben Zeit auf dem Magier aktiv sein. Hält 30 min lang an." }
entries[27126] = { ["name"] = "Arkane Intelligenz", ["text"] = "31% von Grundmana 30 Meter Reichweite\nSofort\nErhöht 30 min lang die Intelligenz des Ziels um 40." }
entries[27127] = { ["name"] = "Arkane Brillanz", ["text"] = "81% von Grundmana 40 Meter Reichweite\nSofort\nReagenzien:\nArkanes Pulver\nErfüllt alle Gruppen- und Schlachtzugsmitglieder mit Brillanz und erhöht Ihre Intelligenz 1 hour lang um 40." }
entries[27128] = { ["name"] = "Feuerzauberschutz", ["text"] = "16% von Grundmana\nSofort 30 sek. Abklingzeit\nAbsorbiert 1125 Feuerschaden. Hält 30 sec lang an." }
entries[27130] = { ["name"] = "Magie verstärken", ["text"] = "27% von Grundmana 30 Meter Reichweite\nSofort\nVerstärkt gegen das anvisierte Gruppenmitglied gerichtete Magie, wobei der von Zaubern zugefügte Schaden um bis zu 90 und Heilzauber um bis zu 96 erhöht werden. Hält 10 min lang an." }
entries[27131] = { ["name"] = "Manaschild", ["text"] = "7% von Grundmana\nSofort\nAbsorbiert 715 Schaden und entzieht stattdessen Mana. Entzieht pro absorbiertem Schaden 1.5 Mana. Hält 1 min lang an." }
entries[27132] = { ["name"] = "Pyroschlag", ["text"] = "22% von Grundmana 35 Meter Reichweite\nWirken in 5 sek.\nSchleudert einen immensen feurigen Felsen, der 876 to 1104 Feuerschaden sowie zusätzlich 12 sec lang insgesamt 312 Feuerschaden verursacht." }
entries[27133] = { ["name"] = "Druckwelle", ["text"] = "7% von Grundmana\nSofort 30 sek. Abklingzeit\nEine Flammenwelle geht vom Zaubernden aus. Alle Feinde, die sich im Radius der Flammen befinden, erleiden 545 to 640 Feuerschaden, werden zurückgestoßen und sind 6 sec lang benommen." }
entries[27134] = { ["name"] = "Eisbarriere", ["text"] = "21% von Grundmana\nSofort 30 sek. Abklingzeit\nSchirmt Euch sofort ab und absorbiert 952 Schaden. Hält 1 min lang an. Solange der Schild hält, werden Zauber durch erlittenen Schaden nicht verzögert." }
entries[27135] = { ["name"] = "Heiliges Licht", ["text"] = "29% von Grundmana 40 Meter Reichweite\nWirken in 2.5 sek.\nHeilt ein befreundetes Ziel um 2264 to 2518." }
entries[27136] = { ["name"] = "Heiliges Licht", ["text"] = "29% von Grundmana 40 Meter Reichweite\nWirken in 2.5 sek.\nHeilt ein befreundetes Ziel um 2846 to 3166." }
entries[27137] = { ["name"] = "Lichtblitz", ["text"] = "7% von Grundmana 40 Meter Reichweite\nWirken in 1.5 sek.\nHeilt ein befreundetes Ziel um 600 to 670." }
entries[27138] = { ["name"] = "Exorzismus", ["text"] = "8% von Grundmana 30 Meter Reichweite\nWirken in 1.5 sek. 15 sek. Abklingzeit\nVerursacht (687 + 0.15 * Spell power + 0.15 * Attack power) bis (765 + 0.15 * Spell power + 0.15 * Attack power) Heiligschaden an einem feindlichen Ziel. Ist das Ziel untot oder dämonisch wird der Zauber stets kritisch treffen." }
entries[27139] = { ["name"] = "Heiliger Zorn", ["text"] = "20% von Grundmana\nSofort 30 sek. Abklingzeit\nSchleudert Blitze heiliger Macht in alle Richtungen, die untoten und dämonischen Zielen im Umkreis von 10 Metern (777 + 0.07 * Spell power + 0.07 * Attack power) bis (913 + 0.07 * Spell power + 0.07 * Attack power) Heiligschaden zufügen und sie 3 sec lang betäuben." }
entries[27140] = { ["name"] = "Segen der Macht", ["text"] = "5% von Grundmana 30 Meter Reichweite\nSofort\nBelegt ein befreundetes Ziel mit einem Segen und erhöht 10 min lang die Angriffskraft um 306. Spieler können pro Paladin immer nur mit einem einzigen Segen belegt sein." }
entries[27141] = { ["name"] = "Großer Segen der Macht", ["text"] = "10% von Grundmana 40 Meter Reichweite\nSofort\nReagenzien:\nSymbol der Könige\nBelegt alle Mitglieder einer Gruppe oder eines Schlachtzuges, die dieselbe Klasse wie das Ziel haben, mit dem großen Segen der Macht. Der große Segen der Macht erhöht die Angriffskraft 30 min lang um 306. Spieler können pro Paladin immer nur mit einem einzigen Segen belegt sein." }
entries[27142] = { ["name"] = "Segen der Weisheit", ["text"] = "5% von Grundmana 30 Meter Reichweite\nSofort\nBelegt ein befreundetes Ziel mit einem Segen und stellt 10 min lang alle 5 Sek. 41 Mana wieder her. Spieler können pro Paladin immer nur mit einem einzigen Segen belegt sein." }
entries[27143] = { ["name"] = "Großer Segen der Weisheit", ["text"] = "11% von Grundmana 40 Meter Reichweite\nSofort\nReagenzien:\nSymbol der Könige\nBelegt alle Mitglieder einer Gruppe oder eines Schlachtzuges, die dieselbe Klasse wie das Ziel haben, mit dem großen Segen der Weisheit. Der große Segen der Weisheit stellt 30 min lang alle 5 Sek. 41 Mana wieder her. Spieler können pro Paladin immer nur mit einem einzigen Segen belegt sein." }
entries[27146] = { ["name"] = "Linkes Stück von Lord Valthalaks Amulett", ["text"] = "Wirken in 2 sek.\nReagenzien:\nObere Stück von Lord Valthalaks Amulett , Rechtes Stück von Lord Valthalaks Amulett\nFügt das linke, rechte und obere Stück von Lord Valthalaks Amulett wieder zu einem Ganzen zusammen." }
entries[27149] = { ["name"] = "Aura der Hingabe", ["text"] = "Sofort\nGibt Gruppen- und Schlachtzugsmitgliedern in einem Umkreis von 40 Metern 861 zusätzliche Rüstung. Spieler können pro Paladin immer nur jeweils eine Aura besitzen." }
entries[27150] = { ["name"] = "Aura der Vergeltung", ["text"] = "Sofort\nVerursacht bei jedem Feind, der ein Gruppen- oder Schlachtzugsmitglied schlägt, das sich im Umkreis von 40 Metern befindet, 62 Heiligschaden. Spieler können pro Paladin nur jeweils eine Aura besitzen." }
entries[27151] = { ["name"] = "Aura des Schattenwiderstands", ["text"] = "Sofort\nVerleiht allen sich im Umkreis von 40 Metern befindlichen Gruppen- und Schlachtzugsmitgliedern zusätzliche 70 Schattenwiderstand. Spieler können pro Paladin immer nur jeweils eine Aura besitzen." }
entries[27152] = { ["name"] = "Aura des Frostwiderstands", ["text"] = "Sofort\nErhöht den Frostwiderstand aller sich im Umkreis von 40 Metern befindlichen Gruppen- und Schlachtzugsmitglieder um 70. Spieler können pro Paladin immer nur jeweils eine Aura besitzen." }
entries[27153] = { ["name"] = "Aura des Feuerwiderstands", ["text"] = "Sofort\nErhöht den Feuerwiderstand aller sich im Umkreis von 40 Metern befindlichen Gruppen- und Schlachtzugsmitglieder um 70. Spieler können pro Paladin immer nur jeweils eine Aura besitzen." }
entries[27154] = { ["name"] = "Handauflegung", ["text"] = "40 Meter Reichweite\nSofort 20 min Abklingzeit\nHeilt ein befreundetes Ziel um einen Betrag, der der maximalen Gesundheit des Paladins entspricht, und stellt 900 seines Manas wieder her. Wirkt der Paladin diesen Zauber auf sich selbst, kann er 2 min lang nicht zum Ziel von 'Gottesschild', 'Göttlicher Schutz', 'Hand des Schutzes' oder auf sich selbst gewirkte 'Handauflegung' werden. Zudem kann der Zaubernde den Zauber nicht innerhalb von 30 sec nach Nutzung von 'Zornige Vergeltung' auf sich selbst wirken." }
entries[27173] = { ["name"] = "Weihe", ["text"] = "22% von Grundmana\nSofort 8 sek. Abklingzeit\nWeiht das Land unter dem Paladin. Alle Feinde, die das Gebiet betreten, erleiden 8 sec lang im Verlauf der Zeit [8 * (72 + 0.04 * Spell power + 0.04 * Attack power)] Heiligschaden." }
entries[27174] = { ["name"] = "Heiliger Schock", ["text"] = "18% von Grundmana 20 Meter Reichweite\nSofort 6 sek. Abklingzeit\nTrifft das Ziel mit heiliger Energie. Verursacht 693 to 749 Heiligschaden bei Feinden oder heilt 1061 to 1149 bei Verbündeten." }
entries[27175] = { ["name"] = "Heiliger Schock", ["text"] = "100 Meter Reichweite\nSofort\nTrifft das Ziel mit heiliger Energie. Verursacht 693 to 749 Heiligschaden bei Feinden oder heilt 1061 to 1149 bei Verbündeten." }
