entries[27177] = { ["name"] = "Entweiht", ["text"] = "Unbegrenzte Reichweite\nKanalisiert (Wirken in 10 sek.)\nVerderbt das Ziel und verwandelt es 10 sec lang in einen spektralen Assassinen. Wird der Zaubernde nicht getötet, stirbt das Ziel, sobald es vollständig verderbt ist." }
entries[27179] = { ["name"] = "Heiliger Schild", ["text"] = "10% von Grundmana\nSofort 8 sek. Abklingzeit\nErhöht die Blockchance 10 sec lang um 30% und verursacht, solang aktiv, mit jedem geblockten Angriff 208 Heiligschaden. Jedes Blocken verbraucht eine der 8 Aufladungen." }
entries[27180] = { ["name"] = "Hammer des Zorns", ["text"] = "12% von Grundmana 30 Meter Reichweite\nSofort 6 sek. Abklingzeit\nSchleudert einen Hammer, der bei einem Feind (733 + 0.15 * Spell power + 0.15 * Attack power) bis (809 + 0.15 * Spell power + 0.15 * Attack power) Heiligschaden verursacht. Nur auf Ziele anwendbar, die über 20% oder weniger Gesundheit verfügen." }
