entries[27186] = { ["name"] = "Tödliches Gift VII", ["text"] = "Wirken in 3 sek.\nBenötigt Nahkampfwaffe\nÜberzieht eine Waffe mit Gift, das eine Stunde lang wirkt.\nBei jedem Schlag besteht eine Chance von 30%, den Gegner 12 sec lang zu vergiften und (51 * 4 + 0.12 * Attack power) Naturschaden zu verursachen. Bis zu 5-mal auf einem einzelnen Ziel stapelbar. Sobald 5 Stapel erreicht sind, führt jede weitere Anwendung des tödlichen Gifts dazu, dass auch das Gift der anderen Waffe auf das Ziel wirkt.\n(Procchance: 30%)" }
entries[27187] = { ["name"] = "Tödliches Gift VII", ["text"] = "100 Meter Reichweite\nSofort\nÜberzieht eine Waffe mit Gift, das eine Stunde lang wirkt.\nBei jedem Schlag besteht eine Chance von 30%, den Gegner 12 sec lang für (51 * 4 + 0.12 * Attack power) Naturschaden zu vergiften. Bis zu 5-mal auf einem einzelnen Ziel stapelbar." }
