entries[27210] = { ["name"] = "Sengender Schmerz", ["text"] = "8% von Grundmana 30 Meter Reichweite\nWirken in 1.5 sek.\nFügt dem Ziel sengenden Schmerz zu und verursacht 252 to 297 Feuerschaden. Verursacht ein hohes Maß an Bedrohung." }
entries[27211] = { ["name"] = "Seelenfeuer", ["text"] = "9% von Grundmana 30 Meter Reichweite\nWirken in 6 sek.\nReagenzien:\nSeelensplitter\nVerbrennt die Seele eines Feindes und verursacht 853 to 1065 Feuerschaden." }
entries[27212] = { ["name"] = "Feuerregen", ["text"] = "57% von Grundmana 30 Meter Reichweite\nKanalisiert (Wirken in 8 sek.)\nLässt einen feurigen Regen niedergehen, der 8 sec lang Feinde im Wirkungsbereich mit insgesamt ( 456 * 4) Feuerschaden verbrennt." }
entries[27213] = { ["name"] = "Höllenfeuer", ["text"] = "64% von Grundmana\nKanalisiert (Wirken in 15 sek.)\nEntzündet den Bereich um den Zaubernden herum, fügt ihm selbst alle 1 Sek. 314 Feuerschaden zu sowie im gleichen Rhythmus allen in der Nähe befindlichen Feinden 314 Feuerschaden. Hält 15 sec lang an." }
entries[27214] = { ["name"] = "Höllenfeuereffekt", ["text"] = "Sofort\nEntzündet den Bereich um den Zaubernden herum, fügt ihm selbst alle 1 Sek. 314 Feuerschaden zu sowie im gleichen Rhythmus allen in der Nähe befindlichen Feinden 314 Feuerschaden. Hält 15 sec lang an." }
entries[27215] = { ["name"] = "Feuerbrand", ["text"] = "17% von Grundmana 30 Meter Reichweite\nWirken in 2 sek.\nVerbrennt den Feind und fügt 349 Feuerschaden sowie 15 sec lang insgesamt 615 zusätzlichen Feuerschaden zu." }
entries[27216] = { ["name"] = "Verderbnis", ["text"] = "14% von Grundmana 30 Meter Reichweite\nSofort\nVerdirbt das Ziel und verursacht 18 sec lang insgesamt 900 Schattenschaden." }
entries[27217] = { ["name"] = "Seelendieb", ["text"] = "14% von Grundmana 30 Meter Reichweite\nKanalisiert (Wirken in 15 sek.)\nEntzieht dem Ziel die Seele und verursacht 15 sec lang insgesamt 620 Schattenschaden. Besitzt das Ziel 25% Gesundheit oder weniger, verursacht 'Seelendieb' den vierfachen Schaden. Wenn das Ziel beim Entziehen der Seele stirbt und Erfahrung oder Ehrenpunkte abgibt, erhält der Zaubernde einen Seelensplitter. Jedes Mal, wenn 'Seelendieb' Schaden verursacht, besteht ebenfalls eine Chance, dass ein Seelensplitter erzeugt wird. Seelensplitter werden für andere Zauber benötigt." }
entries[27218] = { ["name"] = "Fluch der Pein", ["text"] = "10% von Grundmana 30 Meter Reichweite\nSofort\nVerflucht das Ziel mit Pein und fügt 24 sec lang 1356 Schattenschaden zu. Zuerst wird der Schaden langsam zugefügt und nimmt dann zu, bis der Fluch seine Gesamtdauer erreicht hat. Es kann immer nur jeweils ein Fluch pro Hexenmeister auf einem beliebigen Ziel aktiv sein." }
entries[27219] = { ["name"] = "Blutsauger", ["text"] = "17% von Grundmana 30 Meter Reichweite\nKanalisiert (Wirken in 5 sek.)\nÜberträgt alle 1 Sek. 87 Gesundheit vom Ziel auf den Zaubernden. Hält 5 sec lang an." }
entries[27220] = { ["name"] = "Blutsauger", ["text"] = "17% von Grundmana 30 Meter Reichweite\nKanalisiert (Wirken in 5 sek.)\nÜberträgt alle 1 Sek. 108 Gesundheit vom Ziel auf den Zaubernden. Hält 5 sec lang an." }
entries[27222] = { ["name"] = "Aderlass", ["text"] = "Sofort\nWandelt ( 1164 + Spirit * 1.5) Gesundheit in [ 1164 * ( 1 ) + Spell power * .5 * ( 1 )] Mana um. Zaubermacht erhöht die Menge der umgewandelten Gesundheit." }
entries[27223] = { ["name"] = "Todesmantel", ["text"] = "23% von Grundmana 30 Meter Reichweite\nSofort 2 min Abklingzeit\nVerursacht 540 Schattenschaden und das betroffene Ziel läuft 3 sec lang voller Entsetzen davon. Der Zaubernde erhält 300% des verursachten Schadens in Gesundheit." }
entries[27224] = { ["name"] = "Fluch der Schwäche", ["text"] = "10% von Grundmana 30 Meter Reichweite\nSofort\nDie Nahkampfangriffskraft des Ziels wird um 257 verringert, seine Rüstung um 5%. Hält 2 min lang an. Es kann immer nur jeweils ein Fluch pro Hexenmeister auf einem beliebigen Ziel aktiv sein." }
entries[27225] = { ["name"] = "Rüstung des Begleiters +10% erhöht", ["text"] = "Erhöht die Rüstung Eures Begleiters um 10%." }
entries[27228] = { ["name"] = "Fluch der Elemente", ["text"] = "10% von Grundmana 30 Meter Reichweite\nSofort\nVerflucht das Ziel und verringert 5 min lang seinen Arkan-, Feuer-, Frost-, Natur- und Schattenwiderstand um 88. Erhöht außerdem den erlittenen Magieschaden des Ziels um 11%. Es kann immer nur jeweils ein Fluch pro Hexenmeister auf einem beliebigen Ziel aktiv sein." }
entries[27230] = { ["name"] = "Gesundheitsstein herstellen", ["text"] = "53% von Grundmana\nWirken in 3 sek.\nReagenzien:\nSeelensplitter , Item #-2\nLässt einen meisterlichen Gesundheitsstein entstehen, der verwendet werden kann, um sofort 2080 Gesundheit wiederherzustellen.\n\nHerbeigezauberte Gegenstände verschwinden, wenn Ihr Euch länger als 15 Minuten ausloggt." }
entries[27235] = { ["name"] = "Meisterlicher Gesundheitsstein", ["text"] = "Sofort\nStellt sofort 2080 Gesundheit wieder her." }
entries[27236] = { ["name"] = "Meisterlicher Gesundheitsstein", ["text"] = "Sofort\nStellt sofort 2288 Gesundheit wieder her." }
entries[27237] = { ["name"] = "Meisterlicher Gesundheitsstein", ["text"] = "Sofort\nStellt sofort 2496 Gesundheit wieder her." }
entries[27238] = { ["name"] = "Seelenstein herstellen", ["text"] = "68% von Grundmana\nWirken in 3 sek.\nReagenzien:\nSeelensplitter\nLässt einen meisterlichen Seelenstein entstehen. Der Seelenstein kann zum Speichern der Seele eines Ziels benutzt werden. Wenn das Ziel stirbt, während seine Seele gespeichert ist, kann es mit 2900 Gesundheit und 3300 Mana wiederbelebt werden.\n\nHerbeigezauberte Gegenstände verschwinden, wenn Ihr Euch länger als 15 Minuten ausloggt." }
entries[27239] = { ["name"] = "Seelensteinauferstehung", ["text"] = "30 Meter ReichweiteWirken in 3 sek. 15 min Abklingzeit\nSpeichert die Seele des befreundeten Ziels. Wenn das Ziel stirbt, während seine Seele gespeichert ist, kann es sich mit 2900 Gesundheit und 3300 Mana wiederbeleben." }
entries[27240] = { ["name"] = "Seelenstein benutzen" }
entries[27241] = { ["name"] = "Gurky", ["text"] = "Sofort\nMit Rechtsklick Gurky den Babymurloc beschwören und freigeben." }
entries[27242] = { ["name"] = "Belohnung UND Questobjekt erhalten, Wache von Sturmwind", ["text"] = "30 Meter Reichweite\nSofort 3 sek. Abklingzeit\nReagenzien:\nZeichen der Liebe" }
entries[27243] = { ["name"] = "Saat der Verderbnis", ["text"] = "34% von Grundmana 30 Meter Reichweite\nWirken in 2 sek.\nPflanzt dem feindlichen Ziel eine Saat der Verderbnis ein, die im Verlauf von 18 sec 1044 Schattenschaden verursacht. Wenn das Ziel insgesamt 1044 Schaden erleidet oder stirbt, verursacht die Saat bei allen anderen Feinden im Umkreis von 15 Metern um das Ziel 1110 to 1290 Schattenschaden. Auf jedem Ziel kann pro Hexenmeister nur ein Verderbniszauber aktiv sein." }
entries[27244] = { ["name"] = "Belohnung UND Questobjekt erhalten, Wache von Eisenschmiede", ["text"] = "30 Meter Reichweite\nSofort 3 sek. Abklingzeit\nReagenzien:\nZeichen der Liebe" }
