entries[27259] = { ["name"] = "Lebenslinie", ["text"] = "99 Gesundheit und 65 pro Sek. 45 Meter Reichweite\nKanalisiert (Wirken in 10 sek.)\nGibt dem Begleiter des Zaubernden 10 sec lang in jeder Sekunde 188 Gesundheit, solange der Zaubernde seine Kräfte kanalisiert." }
entries[27260] = { ["name"] = "Dämonenrüstung", ["text"] = "31% von Grundmana\nSofort\nSchützt den Zaubernden, erhöht die Rüstung um 1460 und erhöht die durch Zauber und Effekte erzeugte Gesundheit um 20%. Es kann immer nur ein Rüstungszauber zur selben Zeit auf dem Hexenmeister aktiv sein. Hält 30 min an." }
