entries[27263] = { ["name"] = "Schattenbrand", ["text"] = "20% von Grundmana 20 Meter Reichweite\nSofort 15 sek. Abklingzeit\nReagenzien:\nSeelensplitter\nÜberzieht das Ziel sofort mit 538 to 599 Schattenschaden. Wenn das Ziel innerhalb von 5 sec nach 'Schattenbrand' stirbt und Erfahrung oder Ehrenpunkte gewährt, erhält der Zaubernde einen Seelensplitter." }
entries[27265] = { ["name"] = "Dunkler Pakt", ["text"] = "100 Meter Reichweite\nSofort\nZieht 700 Mana Eures beschworenen Dämons ab und gibt 100% an Euch zurück." }
entries[27267] = { ["name"] = "Feuerblitz", ["text"] = "145 Mana 30 Meter Reichweite\nWirken in 2.5 sek.\nVerursacht 117 to 131 Feuerschaden am Ziel." }
entries[27268] = { ["name"] = "Blutpakt", ["text"] = "20 Meter Reichweite\nSofort\nErhöht die die Gesundheit aller Gruppen- und Schlachtzugsmitglieder um 660." }
entries[27269] = { ["name"] = "Feuerschild", ["text"] = "210 Mana 30 Meter Reichweite\nSofort\nUmgibt das befreundete Gruppen- oder Schlachtzugsmitglied mit einem Schild aus Feuer. Der Feuerwiderstand des Zieles wird um 30 erhöht und jeder Schlag gegen das Ziel verursacht beim Angreifer 19 Feuerschaden. Hält 3 min lang an. Der Zaubernde kann 'Feuerschild' nicht auf sich selbst wirken." }
