entries[27271] = { ["name"] = "Leiden", ["text"] = "305 Mana Nahkampfreichweite\nSofort 2 min Abklingzeit" }
entries[27272] = { ["name"] = "Schatten verzehren", ["text"] = "595 Mana\nKanalisiert (Wirken in 6 sek.)\nDer Leerwandler verzehrt in der Nähe befindliche Schatten, um seine Dichte zu erhöhen. Stellt im Laufe von 6 sec insgesamt 2463 Gesundheit wieder her und erhöht die Verstohlenheitsentdeckung aller freundlichen Ziele innerhalb von 30 Metern um einen erheblichen Betrag. Kann nicht während eines Kampfes verwendet werden." }
entries[27273] = { ["name"] = "Opferung", ["text"] = "Unbegrenzte Reichweite\nSofort 1 min Abklingzeit\nOpfert einen Teil der Gesundheit des Leerwandlers und gewährt seinem Besitzer einen Schild, der 30 sec lang 2900 Schaden absorbiert. Solange der Schild hält, wird das Zauberwirken durch erlittenen Schaden nicht unterbrochen." }
entries[27274] = { ["name"] = "Schmerzenspeitsche", ["text"] = "190 Mana Nahkampfreichweite\nSofort 12 sek. Abklingzeit\nEin sofortiger Angriff, der das Ziel peitscht und 123 Schattenschaden zufügt." }
