entries[27827] = { ["name"] = "Geist der Erlösung", ["text"] = "Sofort\nErhöht die gesamte Willenskraft um 5% und beim Tod verwandelt sich der Priester 15 sec lang in einen Geist der Erlösung. Der Geist kann sich weder bewegen oder angreifen, noch kann er das Ziel von Zaubern oder Effekten sein. In dieser Gestalt kann der Priester jeglichen Heilzauber ohne irgendwelche Kosten wirken. Nach Ablauf der Verwandlung stirbt der Priester." }
