entries[27832] = { ["name"] = "Weisenklinge", ["text"] = "Wirken in 50 sek.\nTools:\nSchmiedehammer\nReagenzien:\nArkanitbarren (12), Nexuskristall (2), Fläschchen der obersten Macht (2), Verzaubertes Leder (4)\nWeisenklinge\nWird beim Anlegen gebunden\nWaffenhand Schwert\n49 - 100 Schaden Tempo 1.80\n(41.39 Schaden pro Sekunde)\n+14 Ausdauer\n+6 Intelligenz\nHaltbarkeit 105 / 105\n59\nAnlegen: Erhöht die Zaubermacht um 20.\nAnlegen: Erhöht Eure Zauberdurchschlagskraft um 10." }
