entries[28267] = { ["name"] = "Knusperspinne Surprise", ["text"] = "Wirken in 2 sek.\nReagenzien:\nKnuspriges Spinnenbein\n5\nBenutzen: Stellt im Verlauf von 21 sec 243.6 Gesundheit wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sekunden lang mit Essen verbringt, werdet Ihr satt und erhaltet 15 min lang 4 Ausdauer und Willenskraft." }
