entries[28271] = { ["name"] = "Verwandlung", ["text"] = "7% von Grundmana 30 Meter Reichweite\nWirken in 1.5 sek.\nVerwandelt den Feind in eine Schildkröte und zwingt ihn, 50 sec lang so herumzuwandern. Während die Schildkröte herumwandert, kann sie weder angreifen noch Zauber wirken, regeneriert sich aber sehr schnell. Jeglicher erlittene Schaden verwandelt das Ziel in seine normale Gestalt zurück. Es kann immer nur jeweils ein Ziel verwandelt werden. Wirkt nur bei Wildtieren, Humanoiden und Tieren." }
entries[28272] = { ["name"] = "Verwandlung", ["text"] = "7% von Grundmana 30 Meter Reichweite\nWirken in 1.5 sek.\nVerwandelt den Feind in ein Schwein und zwingt ihn, 50 sec lang so herumzuwandern. Während das Schwein herumwandert, kann es weder angreifen noch Zauber wirken, regeneriert sich aber sehr schnell. Jeglicher erlittene Schaden verwandelt das Ziel in seine normale Gestalt zurück. Es kann immer nur jeweils ein Ziel verwandelt werden. Wirkt nur bei Wildtieren, Humanoiden und Tieren." }
