entries[28275] = { ["name"] = "Brunnen des Lichts", ["text"] = "17% von Grundmana 40 Meter Reichweite\nWirken in 0.5 sek. 3 min Abklingzeit\nErschafft einen heiligen Brunnen des Lichts. Befreundete Spieler können den Brunnen des Lichts anklicken, um im Verlauf von 6 sec insgesamt 2361 Gesundheit wiederherzustellen. Erlittener Schaden, der 30% Eurer gesamten Gesundheit entspricht, bricht den Effekt ab. Der Brunnen des Lichts bleibt 3 min lang bestehen oder bis 10 Aufladungen verbraucht sind." }
