entries[28293] = { ["name"] = "Kettenblitzschlag", ["text"] = "45 Meter Reichweite\nWirken in 2 sek.\nSchlägt in der Nähe befindliche Feinde mit einem Blitzschlag, der auf einen in der Nähe befindlichen Feind überspringt. Der Zauber wirkt sich auf bis zu 3 Ziele aus und verursacht bei jedem folgenden Ziel immer größeren Naturschaden." }
